/**
 * Extend the base Actor document by defining a custom roll data structure which is ideal for the Simple system.
 * @extends {Actor}
 */
export class EatTheReichActor extends Actor {
  /** @override */
  prepareData() {
    // Prepare data for the actor. Calling the super version of this executes
    // the following, prepareBaseData(), prepareEmbeddedDocuments(),
    // prepareDerivedData().
    super.prepareData();
  }

  /**
   *
   * @override
   * Augment the actor's default getRollData() method by appending the data object
   * generated by the its DataModel's getRollData(), or null. This polymorphic
   * approach is useful when you have actors & items that share a parent Document,
   * but have slightly different data preparation needs.
   */
  getRollData() {
    return { ...super.getRollData(), ...(this.system.getRollData?.() ?? null) };
  }

  static ICONS_PATH = `systems/eat-the-reich/assets/icons/`;

  static getDefaultArtwork(actorData) {
    switch (actorData.type) {
			case 'character': {
				return {
          img: `${this.ICONS_PATH}fanged-skull.svg`,
          texture: {
            src: `${this.ICONS_PATH}fanged-skull.svg`,
          },
        };
			}
      case 'location': {
				return {
          img: `${this.ICONS_PATH}occupy.svg`,
          texture: {
            src: `${this.ICONS_PATH}occupy.svg`,
          },
        };
			}
			default: {
				return {
          img: this.DEFAULT_ICON,
          texture: {
            src: this.DEFAULT_ICON,
          },
        };
			}
		}
  }
}
